def count_valid_triangles(nums):
    nums=sorted(nums);answer=0
    for right in range(len(nums)-1,1,-1):
        left,middle=0,right-1
        while left<middle:
            if nums[left]+nums[middle]>nums[right]:answer+=middle-left;middle-=1
            else:left+=1
    return answer

